// French names and descriptions for the core's settings (the core reports them in English; option
// labels are translated by the core itself from RPCS3Core.strings).

enum SettingNames {
    static func category(_ s: String) -> String { categories[s] ?? s }
    static func section(_ s: String) -> String { sections[s] ?? s }
    static func name(_ setting: Setting) -> String { names[setting.key]?.0 ?? setting.name }
    static func detail(_ setting: Setting) -> String { names[setting.key]?.1 ?? setting.detail }

    static let categoryOrder = ["CPU", "GPU", "Audio", "System", "Network", "Emulator", "Advanced", "Experimental", "Debug"]

    static let categoryIcons = [
